import os
os.environ['OPENBLAS_NUM_THREADS']='1'
import numpy as np,json,time
from pathlib import Path
from neural import NeuralModel
z=np.load('/challenge/observations.npz');x=z['tokens'];y=z['probabilities'];h=np.load('/output/hmm5.npz');pi,E,A=[h[k] for k in ['pi','E','A']]
rng=np.random.default_rng(301); N=768; xs=np.empty((N,24),np.int64)
# Independent discovery histories: 512 draws from the current mechanism, 128 uniform, 128 deliberately switched regimes.
for i in range(512):
 s=rng.choice(5,p=pi)
 for t in range(24):xs[i,t]=rng.choice(16,p=E[s]);s=rng.choice(5,p=A[s])
xs[512:640]=rng.integers(0,16,(128,24))
for i in range(640,768):
 ids1,ids2=([0,2,3],[1,4]) if i%2 else ([1,4],[0,2,3]); split=int(rng.integers(4,19))
 for t in range(24):
  ids=ids1 if t<split else ids2;s=int(rng.choice(ids));xs[i,t]=rng.choice(16,p=E[s])
model=NeuralModel(Path('/challenge'));ys=[]
for i in range(0,N,96):
 inp=np.column_stack([np.full(min(96,N-i),16),xs[i:i+96,:23]]).astype(np.int64)
 prob,_=model.forward(inp);ys.append(prob)
ys=np.concatenate(ys);np.savez('/output/discovery.npz',tokens=xs,probabilities=ys,kind=np.repeat([0,1,2],[512,128,128]))
# Controlled causal interventions, used only as structural evidence.
inp=np.column_stack([np.full(32,16),x[:32,:23]]).astype(np.int64)
base,tr=model.forward(inp)
u,s,v=np.linalg.svd(y.reshape(-1,16)-y.reshape(-1,16).mean(0),full_matrices=False)
interventions={}
for kind in ['head','mlp']:
 for l in range(2):
  for head in (range(4) if kind=='head' else [-1]):
   kw={'ablate_heads':((l,head),)} if kind=='head' else {'ablate_mlps':(l,)}
   prob,_=model.forward(inp,**kw);delta=prob-base
   key='%s_%d_%d'%(kind,l,head)
   interventions[key]={'KL':float(np.mean(np.sum(base*np.log(base/prob),-1))),'pc_rms':np.sqrt(np.mean((delta@v[:4].T)**2,axis=(0,1))).tolist()}
   print(key,interventions[key])
# Attention localization from declared q/k operations, not a second full neural execution.
attention=[]
for layer in range(2):
 name='blocks.%d'%layer;res=tr[name+'.residual_input'];qkv=model._linear(model._norm(res,name+'.norm1'),name+'.qkv')
 q,k,vv=qkv.reshape(32,24,3,4,16).transpose(2,0,3,1,4)
 scores=q@k.swapaxes(-1,-2)/4;scores[...,np.triu(np.ones((24,24),bool),1)]=-np.inf
 w=np.exp(scores-scores.max(-1,keepdims=True));w/=w.sum(-1,keepdims=True)
 for head in range(4):
  lag=np.arange(24)[:,None]-np.arange(24)[None,:]
  a={'layer':layer,'head':head,'BOS_mass_late':float(w[:,head,12:,0].mean()),'self_mass_late':float(np.diagonal(w[:,head],axis1=-2,axis2=-1)[:,12:].mean()),'mean_lag_late':float((w[:,head,12:]*lag[12:]).sum(-1).mean())}
  attention.append(a);print('attention',a)
previous=json.loads(Path('/output/neural_counts.json').read_text());counts={k:previous[k]+model.counts[k] for k in previous}
print('THIS INSTANCE',model.counts,'CUMULATIVE',counts)
Path('/output/neural_counts.json').write_text(json.dumps(counts,indent=2))
Path('/output/structural_interventions.json').write_text(json.dumps({'interventions':interventions,'attention':attention,'additional_partial_operations':'Recomputed q/k attention scores once per layer for the 32x24 baseline trace; no extra readouts.','instance_counts':model.counts},indent=2))
print('new discovery shapes',xs.shape,ys.shape)
